   295	/** Get the private pusher channel name for a Report. */
   296	function getReportChannelName(reportID: string): string {
   297	    return `${CONST.PUSHER.PRIVATE_REPORT_CHANNEL_PREFIX}${reportID}${CONFIG.PUSHER.SUFFIX}`;
   298	}
